-- Exercise 06 - b
-- Members of municipality 54518 with no email registered
SELECT
    T1.farmer_id, T1.document_number, T1.first_name, T1.last_name,
    T1.birth_date, T1.gender, T1.phone_number, T1.email,
    T1.membership_date, T1.is_active, T1.municipality_code
FROM farm.farmers AS T1
WHERE T1.municipality_code = '54518'
  AND T1.email IS NULL;
    
